int active = @Tag.Highland/Filtration/BackwashActiveFilter;
if (active == 1 && @Tag.Highland/Area500_Filtration/Filter1.HeadLoss < 2.0) { @Tag.Highland/Area500_Filtration/Filter1.Backwashing = 0; @Tag.Highland/Area500_Filtration/Filter1.BackwashCount = @Tag.Highland/Area500_Filtration/Filter1.BackwashCount + 1; active = 0; }
if (active == 2 && @Tag.Highland/Area500_Filtration/Filter2.HeadLoss < 2.0) { @Tag.Highland/Area500_Filtration/Filter2.Backwashing = 0; @Tag.Highland/Area500_Filtration/Filter2.BackwashCount = @Tag.Highland/Area500_Filtration/Filter2.BackwashCount + 1; active = 0; }
if (active == 3 && @Tag.Highland/Area500_Filtration/Filter3.HeadLoss < 2.0) { @Tag.Highland/Area500_Filtration/Filter3.Backwashing = 0; @Tag.Highland/Area500_Filtration/Filter3.BackwashCount = @Tag.Highland/Area500_Filtration/Filter3.BackwashCount + 1; active = 0; }
if (active == 4 && @Tag.Highland/Area500_Filtration/Filter4.HeadLoss < 2.0) { @Tag.Highland/Area500_Filtration/Filter4.Backwashing = 0; @Tag.Highland/Area500_Filtration/Filter4.BackwashCount = @Tag.Highland/Area500_Filtration/Filter4.BackwashCount + 1; active = 0; }
if (active == 0) {
  if (@Tag.Highland/Area500_Filtration/Filter1.HeadLoss > 8.0) { active = 1; @Tag.Highland/Area500_Filtration/Filter1.Backwashing = 1; }
  else if (@Tag.Highland/Area500_Filtration/Filter2.HeadLoss > 8.0) { active = 2; @Tag.Highland/Area500_Filtration/Filter2.Backwashing = 1; }
  else if (@Tag.Highland/Area500_Filtration/Filter3.HeadLoss > 8.0) { active = 3; @Tag.Highland/Area500_Filtration/Filter3.Backwashing = 1; }
  else if (@Tag.Highland/Area500_Filtration/Filter4.HeadLoss > 8.0) { active = 4; @Tag.Highland/Area500_Filtration/Filter4.Backwashing = 1; }
}
@Tag.Highland/Filtration/BackwashActiveFilter = active;
@Tag.Highland/Area500_Filtration/Filter1.InService = @Tag.Highland/Area500_Filtration/Filter1.Backwashing == 1 ? 0 : 1;
@Tag.Highland/Area500_Filtration/Filter2.InService = @Tag.Highland/Area500_Filtration/Filter2.Backwashing == 1 ? 0 : 1;
@Tag.Highland/Area500_Filtration/Filter3.InService = @Tag.Highland/Area500_Filtration/Filter3.Backwashing == 1 ? 0 : 1;
